import numpy as np

def kernel(x):
    M, N = x.shape
    result = np.empty_like(x, dtype=np.float32)

    # Tile size
    tile_rows = 128
    tile_cols = 512

    # Iterate over the array in tiles
    for i in range(0, M, tile_rows):
        for j in range(0, N, tile_cols):
            # Determine the end indices for the current tile
            end_i = min(i + tile_rows, M)
            end_j = min(j + tile_cols, N)

            # Extract the tile
            tile = x[i:end_i, j:end_j]

            # Compute the max value in the tile for numerical stability using explicit loop
            row_count = end_i - i
            col_count = end_j - j
            max_val = np.full(row_count, -np.inf, dtype=np.float32)
            for k in range(col_count):
                for l in range(row_count):
                    if tile[l, k] > max_val[l]:
                        max_val[l] = tile[l, k]

            # Subtract max value from each row using explicit loops
            for l in range(row_count):
                for k in range(col_count):
                    tile[l, k] -= max_val[l]

            # Compute the sum of exponentials along the last axis using explicit loop
            sum_exp = np.zeros(row_count, dtype=np.float32)
            for k in range(row_count):
                col_sum = 0.0
                for l in range(col_count):
                    col_sum += np.exp(tile[k, l])
                sum_exp[k] = col_sum

            # Compute softmax using explicit broadcasting
            for k in range(row_count):
                for l in range(col_count):
                    result[i + k, j + l] = np.exp(tile[k, l]) / sum_exp[k]

    return result
